import{_ as s,a0 as n,w as i,s as l,ao as f,I as o,x as t,a1 as p,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"開源的養家之道 | LCTT x X-CMD","titleTemplate":false,"description":"開源的養家之道 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源的養家之道 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源的養家之道 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230329.0 ⭐️⭐️ The open source way of raising a family","title":"開源的養家之道","tag":"202306","desc":""},"relativePath":"202306/20230329.0 ⭐️⭐️ The open source way of raising a family.md","filePath":"[post].md"}'),m={name:"202306/20230329.0 ⭐️⭐️ The open source way of raising a family.md"};function d(u,e,T,h,x,g){const a=n("Link");return i(),l("div",null,[e[15]||(e[15]=f('<h1 id="開源的養家之道" tabindex="-1">開源的養家之道 <a class="header-anchor" href="#開源的養家之道" aria-label="Permalink to “開源的養家之道”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/15/170832t7yflsv0t2vy5z2v.jpg" alt=""></p><blockquote><p>與你最親近的人建立一種開放的文化，並帶着它走遍天下。</p></blockquote><p>作為 80 年代的叛逆少年，“因為我這麼説”是我在家裏經常聽到的一句話。我並不是一個真正的叛逆者。我只是想讓別人聽到我的聲音，把我看成是一個開始表達自己想法和情感的人。</p><p>我那種不被傾聽/聆聽的感覺讓我相信，培養不害怕説話的孩子很重要，但他們也能學會適應。傾聽他們的意見，與孩子們合作，也可以幫助他們發揮創造力，最終讓他們成為成功組織的一部分。</p><h3 id="孩子們如何解釋信息" tabindex="-1">孩子們如何解釋信息 <a class="header-anchor" href="#孩子們如何解釋信息" aria-label="Permalink to “孩子們如何解釋信息”">​</a></h3><p>我並沒有刻意鼓勵孩子們的開放行為，也沒有主動告訴孩子們要大聲説話。儘管如此，在我大兒子上幼兒園的第一天，他的老師給我們打電話。她告訴我們，當她和全班同學一起討論不打架、不推搡等規則時，我的孩子舉手告訴她，他的父母允許他一直爭論和辯論。</p><p>這是真的。我讓我的孩子們表達自己的意見，並讓他們聽到。但我孩子的話讓我感到驚訝。直到那時我才意識到，雖然我一直在做正確的事情，但事實上，我的孩子們的行為不應該只是對我們教育他們的方式的反應。我們也不應該讓他們從二手語境中挑選東西。那一天對我來説是一個遊戲規則的改變，踐行開放的文化正式主動地進入我們的家庭。</p><h3 id="為成長而開放" tabindex="-1">為成長而開放 <a class="header-anchor" href="#為成長而開放" aria-label="Permalink to “為成長而開放”">​</a></h3><p>在我小的時候，父母和長輩是有知識的人。</p><p>作為一個孩子，要獲得信息並不容易。雖然我被鼓勵表達意見，但也只是到了一個規範的、“容易消化”的程度。今天，父母、老師和孩子都有同樣的手段來獲取數據。你如何處理它，完全取決於你。</p><p>例如，在用希伯來語玩 Scattergories 時，“病毒”一詞通常是大多數人玩的唯一以 “V” 開頭的生物。為了獲得更多的分數，我們決定尋找其他符合條件的動物名稱。不一會兒，我們就找到了不是一種而是三種新的生物（我孩子的老師認為“小袋鼠”（希伯來語中以 “V” 拼寫）不是一種真實的東西，但這是另一個故事）。</p><p>我教我的孩子閲讀字裏行間的內容，決不要不加質疑地接受作為“事實”呈現給他們的東西。這使他們能夠練習批判性思維。這也使他們能夠質疑我，從而使我們進行公開和透明的討論。</p><p>這些討論容易嗎？不是。我總是有精力進行這些討論嗎？絕對不是。</p><p>然而，為了幫助他們練習學會傾聽的“肌肉”，這些對話是必須的。</p><p>偶爾，我們必須強迫自己找到時間，把注意力集中在家庭上。建立一個強大而開放的文化需要時間，隨着人們的變化，你的家庭文化也在變化。你必須適應並努力保持它的活力。作為羣體的領導者，我必須為我的孩子們提供一個安全的地方，一個他們可以公開分享自己想法的地方，一個他們有歸屬感的地方。</p><p>在一個家庭中，你們必須合作，共同解決問題。傾聽不同的想法和解決問題的方法可以讓你想出創造性的（但並不總是符合每個人的喜好）解決方案。</p><p>我家裏的一個問題是玩電腦遊戲時家裏的噪音。這種情況大多發生在深夜和週末。我們一起坐下來，想出了一個商定的嘈雜遊戲的時間段。從那時起，那些想玩的人知道他們什麼時候可以玩，而那些尋求一些安靜時間的人也知道這些時間會發生什麼。隨着孩子們的長大，決定和討論的性質也發生了變化。</p><p>這是否意味着所有的決定都與孩子們分享？不。這是否意味着都是玫瑰花？絕對不是。</p><p>鼓勵孩子們建立聯繫可能會以一個破花瓶告終，似乎沒有人對此負責。這可能會導致“因為我這麼説”來拜訪。然而，進行具有挑戰性但又具有包容性的對話、鼓勵創新思維以及讓孩子參與決策都是讓他們為成年做好準備的方法。希望它也能讓他們成為更好的人（到目前為止，以我的拙見，這運作良好）。</p><h3 id="開放的家庭文化" tabindex="-1">開放的家庭文化 <a class="header-anchor" href="#開放的家庭文化" aria-label="Permalink to “開放的家庭文化”">​</a></h3><p>實行開放的文化不是一次性的事情。它是一個旅程，也是一種心態。我相信它為我和我的孩子們提供了工具，使他們在屋內和屋外都能堅韌不拔、思想開放、寬容和充滿好奇心。與你最親近的人建立一種開放的文化，並帶着它走遍天下。</p><p><em>（題圖：MJ/76568fbf-4e8a-4a9e-9ff1-d6a7e0922622）</em></p><hr>',24)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),p(a,{href:"https://opensource.com/article/23/3/open-source-family"},{default:r(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/23/3/open-source-family",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),p(a,{href:"https://opensource.com/users/rnetser1"},{default:r(()=>[...e[2]||(e[2]=[t("Ruth Netser",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),p(a,{href:"https://github.com/lkxed/"},{default:r(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),p(a,{href:"https://github.com/geekpi"},{default:r(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:r(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const k=s(m,[["render",d]]);export{_ as __pageData,k as default};
